# PATCH_V7_LEDGER_RECOVERY_BEGIN
try{

$ledger="C:\alpaca-bot\ORG_BOT_UNIFIED\runtime\paper\state\risk_ledger_atomic.json"

if(Test-Path $ledger){

    $data=Get-Content $ledger -Raw | ConvertFrom-Json
    $session_id=[guid]::NewGuid().ToString()

    $data.session_id=$session_id
    $data.last_seen=(Get-Date).ToString("s")
    $data.pid=$PID
    $data.kind="atomic_risk_ledger_v7"

    $tmp="$ledger.tmp"
    ($data|ConvertTo-Json -Compress)|Set-Content $tmp -Encoding UTF8
    Move-Item $tmp $ledger -Force
}

}catch{
Write-Host "Ledger recovery guard triggered"
}
# PATCH_V7_LEDGER_RECOVERY_END
